css:
body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans",Helvetica,Arial,sans-serif;}
.chat-markdown code,.chat-markdown-codeblock{font-family:ui-monospace,SFMono-Regular,"SF Mono",Menlo,Consolas,"Liberation Mono",monospace;}
.chat-markdown :not(pre)>code{background:color-mix(in srgb,var(--muted-foreground) 20%,transparent);border-radius:6px;padding:.2em .4em;font-size:85%;}
[data-thread-item]{border-radius:6px!important;}
[data-slot="button"],[data-slot="input"],[data-slot="select-trigger"]{border-radius:6px!important;}
[data-slot="button"]{font-weight:500;}
[data-slot="composer-host"]{border-radius:12px!important;border:1px solid var(--border)!important;box-shadow:none!important;}
[data-slot="composer-host"]:focus-within{border-color:var(--ring,var(--primary))!important;box-shadow:inset 0 0 0 1px var(--ring,var(--primary))!important;}
[data-user-message-bubble]{border-radius:6px!important;border:1px solid var(--border)!important;}
.chat-markdown-codeblock{border-radius:6px!important;border:1px solid var(--border);}
[data-slot="dialog-popup"]{border-radius:12px!important;border:1px solid var(--border)!important;}
[data-slot="popover-popup"],[data-slot="menu-popup"]{border-radius:12px!important;border:1px solid var(--border)!important;box-shadow:0 8px 24px rgba(1,4,9,.2)!important;}
[data-slot="tooltip-popup"]{border-radius:6px!important;}
button.bg-message-action:disabled{background:color-mix(in srgb,var(--foreground) 10%,transparent)!important;color:var(--muted-foreground)!important;opacity:1!important;}
:root:not(.dark) [data-slot="switch"][data-unchecked]{background:#E6EAEF!important;box-shadow:inset 0 0 0 1px #D1D9E0!important;}
:root:not(.dark) [data-slot="switch"][data-unchecked] [data-slot="switch-thumb"]{background:#FFFFFF!important;box-shadow:0 0 0 1px #818B98!important;}
:root:not(.dark) [data-slot="switch"][data-checked]{background:#0969DA!important;box-shadow:none!important;}
:root:not(.dark) [data-slot="switch"][data-checked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
.dark [data-slot="switch"][data-unchecked]{background:#262C36!important;box-shadow:inset 0 0 0 1px #3D444D!important;}
.dark [data-slot="switch"][data-unchecked] [data-slot="switch-thumb"]{background:#9198A1!important;}
.dark [data-slot="switch"][data-checked]{background:#1F6FEB!important;box-shadow:none!important;}
.dark [data-slot="switch"][data-checked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
::-webkit-scrollbar{width:10px;height:10px;}
::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--foreground) 20%,transparent);border-radius:999px;border:2px solid transparent;background-clip:padding-box;}
